CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('ADMIN','EMPLOYEE');
CREATE TYPE movement_type AS ENUM ('IMPORT','SALE','RESERVATION','RESERVATION_RELEASE','RESERVATION_CANCEL','REVERSED','DAMAGE','DESTROYED','LOST','RETURN','CORRECTION','OTHER');
CREATE TYPE payment_method AS ENUM ('CASH','CARD','BANK_TRANSFER','OTHER');
CREATE TYPE reservation_status AS ENUM ('ACTIVE','COMPLETED','CANCELLED','EXPIRED');
CREATE TYPE sale_status AS ENUM ('COMPLETED','CANCELLED','RETURNED','PARTIALLY_RETURNED');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, username text NOT NULL UNIQUE, password_hash text NOT NULL, role user_role NOT NULL DEFAULT 'EMPLOYEE', is_active boolean NOT NULL DEFAULT true, last_login timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text, email text, address text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text, email text, address text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX customers_search_idx ON customers (name, phone);
CREATE TABLE contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, type text NOT NULL DEFAULT 'OTHER', phone text, email text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, category_id uuid REFERENCES categories(id), supplier_id uuid REFERENCES suppliers(id), description text, purchase_price numeric(12,2) NOT NULL DEFAULT 0 CHECK (purchase_price>=0), selling_price numeric(12,2) NOT NULL DEFAULT 0 CHECK (selling_price>=0), current_quantity integer NOT NULL DEFAULT 0 CHECK(current_quantity>=0), reserved_quantity integer NOT NULL DEFAULT 0 CHECK(reserved_quantity>=0 AND reserved_quantity<=current_quantity), width numeric(10,2), height numeric(10,2), depth numeric(10,2), material text, color text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_name_idx ON products(name);
CREATE TABLE product_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, filename text NOT NULL, storage_path text NOT NULL UNIQUE, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE SEQUENCE sales_sale_number_seq;
CREATE TABLE sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_number bigint NOT NULL DEFAULT nextval('sales_sale_number_seq') UNIQUE, customer_id uuid REFERENCES customers(id), employee_id uuid NOT NULL REFERENCES users(id), status sale_status NOT NULL DEFAULT 'COMPLETED', subtotal numeric(12,2) NOT NULL, discount_total numeric(12,2) NOT NULL DEFAULT 0, total numeric(12,2) NOT NULL CHECK(total>=0), notes text, business_date date NOT NULL DEFAULT current_date, delivery_required boolean NOT NULL DEFAULT false, delivery_address text, delivery_date date, delivery_notes text, delivery_status text NOT NULL DEFAULT 'NOT_REQUIRED', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sale_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES sales(id), product_id uuid NOT NULL REFERENCES products(id), supplier_id uuid REFERENCES suppliers(id), quantity integer NOT NULL CHECK(quantity>0), regular_unit_price numeric(12,2) NOT NULL, discount_amount numeric(12,2) NOT NULL DEFAULT 0, final_unit_price numeric(12,2) NOT NULL, line_total numeric(12,2) NOT NULL, cost_price numeric(12,2) NOT NULL);
CREATE TABLE sale_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES sales(id) ON DELETE CASCADE, method payment_method NOT NULL, amount numeric(12,2) NOT NULL CHECK(amount>0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sale_refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES sales(id), sale_item_id uuid NOT NULL REFERENCES sale_items(id), amount numeric(12,2) NOT NULL CHECK(amount>0), reason text NOT NULL, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid REFERENCES products(id) ON DELETE SET NULL, product_name text, action text NOT NULL, user_id uuid NOT NULL REFERENCES users(id), notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), customer_id uuid REFERENCES customers(id), supplier_id uuid REFERENCES suppliers(id), quantity integer NOT NULL CHECK(quantity>0), selling_price numeric(12,2) CHECK(selling_price>=0), deposit_paid numeric(12,2) NOT NULL DEFAULT 0 CHECK(deposit_paid>=0), status reservation_status NOT NULL DEFAULT 'ACTIVE', created_by uuid NOT NULL REFERENCES users(id), expires_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stock_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), type movement_type NOT NULL, quantity integer NOT NULL CHECK(quantity<>0), user_id uuid NOT NULL REFERENCES users(id), reference_id uuid, supplier_id uuid REFERENCES suppliers(id), purchase_price numeric(12,2), business_date date, notes text, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, deleted_by uuid REFERENCES users(id), deletion_reason text);
CREATE INDEX stock_movements_history_idx ON stock_movements(product_id,type,created_at DESC);
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settings (key text PRIMARY KEY, value text NOT NULL);
